-- v2.4: abuse protection — blocks, devices, failed-auth counters, spend reservation.

CREATE TABLE IF NOT EXISTS blocks (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  kind       TEXT NOT NULL,              -- ip | device
  value      TEXT NOT NULL,
  reason     TEXT,
  auto       INTEGER NOT NULL DEFAULT 0, -- 1 = added by the brute-force guard
  expires_at INTEGER,                    -- NULL = permanent
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  UNIQUE (kind, value)
);

-- Devices a key is used from. device_id is a random ID generated by the setup tool on each
-- machine (no hardware identifiers are collected); name/platform are shown to the student too.
CREATE TABLE IF NOT EXISTS devices (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_id  TEXT NOT NULL,
  name       TEXT,
  status     TEXT NOT NULL DEFAULT 'active',   -- active | pending | blocked
  first_seen INTEGER NOT NULL DEFAULT (unixepoch()),
  last_seen  INTEGER,
  last_ip    TEXT,
  UNIQUE (user_id, device_id)
);
CREATE INDEX IF NOT EXISTS idx_devices_device ON devices(device_id);

CREATE TABLE IF NOT EXISTS auth_failures (
  ip       TEXT PRIMARY KEY,
  count    INTEGER NOT NULL,
  first_at INTEGER NOT NULL,
  last_at  INTEGER NOT NULL
);

ALTER TABLE usage_logs ADD COLUMN ip TEXT;
ALTER TABLE usage_logs ADD COLUMN device_id TEXT;
CREATE INDEX IF NOT EXISTS idx_usage_user_time2 ON usage_logs(user_id, created_at, cost);

INSERT OR IGNORE INTO settings (key, value) VALUES ('security', '{
  "device_policy": "track",
  "max_devices": 2,
  "auth_fail_limit": 10,
  "auth_fail_window_min": 10,
  "auto_block_min": 60,
  "user_daily_usd": 3,
  "user_daily_tokens": 15000000,
  "global_daily_upstream_usd": 20,
  "max_body_mb": 20,
  "min_reserve_output_tokens": 1024
}');
